def _run_cleanup_task(self):
    dlg = PermissionDialog(
        action_type="🧹 Workspace Temp Cleanup",
        target="Local Workspace Directory",
        subject="Remove temporary cache & orphaned files",
        body="Authorize Sage AI to clean .pycache and temporary log artifacts in the workspace directory?",
        parent=self
    )
    dlg.exec()
    if dlg.approved:
        cleaned_count = 0
        ws = Path.cwd()
        for root, dirs, files in os.walk(ws):
            for d in list(dirs):
                if d == "__pycache__":
                    p = Path(root) / d
                    try:
                        shutil.rmtree(p, ignore_errors=True)
                        cleaned_count += 1
                    except Exception:
                        pass
            for f in files:
                if f.endswith((".pyc", ".tmp", ".pyo")):
                    try:
                        (Path(root) / f).unlink(missing_ok=True)
                        cleaned_count += 1

