        )
        for entry in entries:
            if entry.name in IGNORED_NAMES or (entry.name.startswith(".") and entry.name != ".env.example"):
                continue

            if entry.is_dir():
                dir_item = QTreeWidgetItem(parent_item, [f"📁 {entry.name}"])
                dir_item.setData(0, Qt.UserRole, f"dir:{entry}")
