def set_history(self, strokes: List[dict]):
    self.strokes = [dict(s) for s in strokes]
    self.update()

def mousePressEvent(self, event):
    if event.button() == Qt.LeftButton:
        pos = event.position()
        pt = (int(pos.x()), int(pos.y()))
        self.current_stroke = {
            "tool": self.active_tool,
            "points": [pt],
            "color": "#050811" if self.active_tool == "eraser" else self.active_color,
            "width": self.active_width * 3 if self.active_tool == "eraser" else self.active_width,
            "peer_name": self.my_name,
            "timestamp": time.time()
        }
        self.update()

def mouseMoveEvent(self, event):
    if event.buttons() & Qt.LeftButton and self.current_stroke:
        pos = event.position()
        pt = (int(pos.x()), int(pos.y()))
        points = self.current_stroke["points"]
        tool = self.current_stroke["tool"]

        if tool in ("pen", "eraser"):
            # Avoid redundant points
            if not points or points[-1] != pt:
                points.append(pt)
        else:
            # Shapes only need start and current end point
            if len(points) == 1:
                points.append(pt)
            else:
                points[-1] = pt

        self.update()

def mouseReleaseEvent(self, event):
    if event.button() == Qt.LeftButton and self.current_stroke:
        pos = event.position()
        pt = (int(pos.x()), int(pos.y()))
        points = self.current_stroke["points"]
        tool = self.current_stroke["tool"]

        if tool in ("pen", "eraser"):
            if not points or points[-1] != pt:
                points.append(pt)
        else:
            if len(points) == 1:
                points.append(pt)
            else:
                points[-1] = pt

        # Only commit if stroke has at least 1 point
        if points:
            stroke_copy = dict(self.current_stroke)
            self.strokes.append(stroke_copy)
            self.stroke_finished.emit(stroke_copy)

        self.current_stroke = None
        self.update()

