def cancel(self):
    """Requests cancellation of worker."""
    self._is_cancelled = True

def run(self):
    try:
        def on_stage(stage: str):
            if not self._is_cancelled:
                self.stage_changed.emit(stage)

        def on_chunk(chunk: str):
            if not self._is_cancelled:
                self.token_received.emit(chunk)

